package bowling

import "errors"

var (
	errNegativeRoll = errors.New("Negative roll is invalid")
	errTooManyPins  = errors.New("Pin count exceeds pins on the lane")
	errGameIsOver   = errors.New("Cannot roll after game is over")
	errNotGameOver  = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of the rolls of a bowling game and can score it once
// all ten frames have been completed.
type Game struct {
	rolls        []int
	frame        int // 0-based index of the current frame (0-9)
	pinsDown     int // pins knocked down in the first roll of the current frame
	rollsInFrame int // rolls already made in the current frame (0 or 1)
	tenthStart   int // index in rolls where the 10th frame begins
	gameOver     bool
}

func NewGame() *Game {
	return &Game{}
}

// Roll records a single ball throw. It returns an error if the roll is
// invalid (negative, more than 10 pins, exceeds the pins on the lane) or
// if the game has already ended.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if g.gameOver {
		return errGameIsOver
	}

	if g.frame < 9 {
		// Frames 1-9: a frame is a strike (one roll) or two rolls.
		if g.pinsDown+pins > 10 {
			return errTooManyPins
		}
		g.rolls = append(g.rolls, pins)
		if g.rollsInFrame == 0 {
			// First roll of the frame.
			if pins == 10 {
				g.advanceFrame()
			} else {
				g.pinsDown = pins
				g.rollsInFrame = 1
			}
		} else {
			// Second roll of the frame (spare or open frame).
			g.advanceFrame()
		}
	} else {
		// The 10th frame: up to three rolls, with bonus rolls after a
		// strike or spare.
		tenth := g.rolls[g.tenthStart:]
		switch len(tenth) {
		case 0:
			// First roll of the 10th frame: always valid (pins <= 10).
			g.rolls = append(g.rolls, pins)
		case 1:
			// Second roll: limited unless the first was a strike.
			if tenth[0] != 10 && tenth[0]+pins > 10 {
				return errTooManyPins
			}
			g.rolls = append(g.rolls, pins)
			// No bonus roll unless the first was a strike or a spare.
			if tenth[0] != 10 && tenth[0]+pins != 10 {
				g.gameOver = true
			}
		case 2:
			// Third (bonus) roll: limited unless the second was a strike.
			if tenth[0] == 10 && tenth[1] != 10 && tenth[1]+pins > 10 {
				return errTooManyPins
			}
			g.rolls = append(g.rolls, pins)
			g.gameOver = true
		}
	}
	return nil
}

// advanceFrame moves to the next frame after a strike or the second roll
// of a frame in frames 1-9.
func (g *Game) advanceFrame() {
	g.frame++
	g.pinsDown = 0
	g.rollsInFrame = 0
	if g.frame == 9 {
		g.tenthStart = len(g.rolls)
	}
}

// Score returns the total score of the game. It returns an error if the
// game has not yet been completed.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errNotGameOver
	}

	rolls := g.rolls
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if frame < 9 {
			if rolls[i] == 10 {
				// Strike: 10 plus the next two rolls.
				score += 10 + rolls[i+1] + rolls[i+2]
				i++
			} else if rolls[i]+rolls[i+1] == 10 {
				// Spare: 10 plus the next roll.
				score += 10 + rolls[i+2]
				i += 2
			} else {
				// Open frame.
				score += rolls[i] + rolls[i+1]
				i += 2
			}
		} else {
			// 10th frame: sum all remaining rolls.
			for ; i < len(rolls); i++ {
				score += rolls[i]
			}
		}
	}
	return score, nil
}
